/*
 * progress.js — Bölüm (section) sıralı ilerleme durumu.
 * Tüm sayfalar (liste, kartlar, bölümler, istatistik) bunu paylaşır.
 *
 * Model (sıralı/kilitli):
 *   FRO = frontier — üzerinde çalışılan sıradaki bölüm (0-based index).
 *   REV = review hedefi (index) veya null — sarı bölümün "Tekrar"ı.
 *   current() = REV != null ? REV : FRO   → liste/kartlar bunu gösterir.
 *
 * Bölüm sınavı (gün sonu sınavı) %100 geçilirse:
 *   - review ise: o bölüm yeşil, tekrar sayacı (rc) +1, REV temizlenir.
 *   - normal ise: o bölüm yeşil (rc=0), FRO bir ilerler (sıradaki açılır).
 * Geçilemezse:
 *   - o bölümün yeşili silinir (gri), liste yeniden açılır. rc korunur.
 *   - review ise REV o bölümde kalır (tekrar çalışılır); normalde FRO aynı kalır.
 *
 * Renk: gray (kayıt yok) / green (geçildi, <2 gün) / yellow (geçildi, >=2 gün,
 *   "Tekrar" bekliyor) / gold (rc>=GOLD: 4 tekrar döngüsü bitti = tam öğrenme,
 *   artık sarıya dönmez, tekrar istenmez).
 */
window.OX = (function () {
  var DAY = 86400000, TWO = 2 * DAY;
  var K_FRO = "ox3000_frontier", K_SEC = "ox3000_sections_v1", K_REV = "ox3000_review";
  var MAX = 29; // 30 bölüm, 0..29
  var GOLD = 4; // 4 tekrar (sarı→sınav) döngüsünden sonra altın = tam öğrenme

  function gi(k, d) { try { var v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } }
  function si(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }

  function frontier() { var f = gi(K_FRO, 0); return Math.max(0, Math.min(MAX, f | 0)); }
  function review() { var r = gi(K_REV, null); return (r == null ? null : (r | 0)); }
  function current() { var r = review(); return r == null ? frontier() : r; }
  function sections() { var s = gi(K_SEC, {}); return (s && typeof s === "object") ? s : {}; }

  function status(no) {
    var s = sections()[no];
    if (!s || s.greenAt == null) return "gray";
    if ((s.rc | 0) >= GOLD) return "gold";                  // tam öğrenme (altın)
    return (Date.now() - s.greenAt >= TWO) ? "yellow" : "green";
  }

  // Sınav sonucu uygula. idx: 0-based bölüm index, no: grup no, pass: %100 mu.
  function examResult(idx, no, pass) {
    var s = sections(), rev = review(), fro = frontier();
    var prev = s[no] || {};
    if (pass) {
      var rc = prev.rc | 0;
      if (rev != null) rc = Math.min(GOLD, rc + 1);         // tekrar başarılı → sayaç +1
      s[no] = { greenAt: Date.now(), rc: rc };
      si(K_SEC, s);
      if (rev != null) { si(K_REV, null); }                 // review bitti → frontier'a dön
      else if (idx === fro && fro < MAX) { si(K_FRO, fro + 1); } // ilerle
      return rc >= GOLD ? "gold" : "green";
    } else {
      if (prev.rc) { s[no] = { rc: prev.rc | 0 }; }         // yeşili sil ama sayacı koru → gri
      else if (s[no]) { delete s[no]; }
      si(K_SEC, s);
      if (rev != null) { si(K_REV, idx); }                  // review başarısız → o bölümde kal
      return "reopen";                                       // liste yeniden açılacak
    }
  }

  function startReview(idx) { si(K_REV, idx); }

  // Tüm ilerlemeyi sıfırla (hile cezası): frontier→0, bölümler ve review temizlenir.
  function reset() {
    try {
      localStorage.removeItem(K_FRO);
      localStorage.removeItem(K_SEC);
      localStorage.removeItem(K_REV);
    } catch (e) {}
  }

  return {
    DAY: DAY, MAX: MAX,
    frontier: frontier, review: review, current: current,
    sections: sections, status: status,
    examResult: examResult, startReview: startReview, reset: reset
  };
})();

srs.js:
/*
 * srs.js — Kelime bazlı aralıklı tekrar (kutu sistemi). Tüm sayfalar paylaşır.
 *
 * Her kelimenin seviyesi:
 *   0 = yeni (hiç sınavda cevaplanmadı, kayıt yok)
 *   1, 2, 3 = öğreniliyor (kutular)
 *   4 = olgun (3. kutuyu geçti, 7 günde bir sorulmaya devam eder)
 * Kutu aralıkları (gün): 1 → 1, 2 → 3, 3 → 7, olgun → 7.
 *
 * Sınavda cevap:
 *   yeni kelime: doğru → 2, yanlış → 1 (artık döngüde, yeni sayılmaz)
 *   döngüdeki:   doğru → bir üst (en çok olgun), yanlış → bir alt (en az 1;
 *                olgun → 2, çünkü olgun da Kutu 3 gibi 7 günlük)
 *   Yanlışta o anki yön (en2tr/tr2en) kilitlenir; doğruda kilit kalkar.
 *
 * Günler yerel saatle gece 00:00'da değişir. Anahtar: "grupNo|kelime"
 * (aynı kelime birden fazla grupta geçebildiği için).
 *
 * Sayfalar önce setCatalog() ile tüm kelimeleri sırasıyla (grup 1 → 30,
 * grup içi sırayla) tanıtır; liste, sınav sırası ve sayaçlar buna göre çıkar.
 */
(typeof window !== "undefined" ? window : globalThis).SRS = (function () {
  var KEY = "ox3000_srs_v1", DAYMS = 86400000;
  var IV = [0, 1, 3, 7, 7];              // seviye → aralık (gün)
  var LV = ["A1", "A2", "B1", "B2", "C1"];
  var CAT = [], IDX = {}, st = null;

  function load() {
    if (st) return st;
    try { st = JSON.parse(localStorage.getItem(KEY) || "{}"); } catch (e) { st = {}; }
    if (!st || typeof st !== "object") st = {};
    return st;
  }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(st)); } catch (e) {} }

  function today(now) {
    var d = new Date(now == null ? Date.now() : now);
    return Math.floor((d.getTime() - d.getTimezoneOffset() * 60000) / DAYMS);
  }
  function key(no, w) { return no + "|" + w; }

  // list: [{k, lv, g}] — k anahtar, lv seviye ("A1"…), g grup index (0..29)
  function setCatalog(list) {
    CAT = list; IDX = {};
    for (var i = 0; i < list.length; i++) IDX[list[i].k] = i;
  }
  // GROUPS dizisinden katalog üret (sayfalardaki gömülü veri biçimi).
  // Aynı grupta aynı kelime ikinci kez geçerse ("set" isim+fiil) anahtara "|2"
  // eklenir. Kelime nesnelerine anahtar it._k olarak iliştirilir; sayfalar hep
  // bunu kullanır, böylece her yerde aynı anahtar çıkar.
  function catalogFromGroups(groups) {
    var out = [];
    for (var g = 0; g < groups.length; g++) {
      var G = groups[g], ws = G.items || G.ws || [], seen = {};
      for (var i = 0; i < ws.length; i++) {
        var w = typeof ws[i] === "string" ? ws[i] : ws[i].w, k = key(G.no, w);
        if (seen[k]) { seen[k]++; k = k + "|" + seen[k]; } else seen[k] = 1;
        if (typeof ws[i] === "object") ws[i]._k = k;
        out.push({ k: k, lv: G.level, g: g });
      }
    }
    return out;
  }

  function rec(k) { return load()[k] || null; }
  function level(k) { var r = rec(k); return r ? r.b : 0; }
  function isNew(k) { return !rec(k); }
  function isDue(k, now) { var r = rec(k); return !!r && r.due <= today(now); }
  function dirOf(k) { var r = rec(k); return (r && r.d) || null; }

  // Sınav cevabı. dir: o an sorulan yön (yanlışsa kilitlenir).
  function answer(k, ok, dir, now) {
    var s = load(), r = s[k], t = today(now), from = r ? r.b : 0, to;
    if (!r) { to = ok ? 2 : 1; r = { b: to, n: 0, l: 0, f: t }; }
    else { to = ok ? Math.min(4, r.b + 1) : Math.max(1, Math.min(r.b, 3) - 1); r.b = to; }
    if (ok) { r.n++; delete r.d; } else { r.l++; if (dir) r.d = dir; }
    r.due = t + IV[to]; r.a = t;
    s[k] = r; save();
    return { from: from, to: to, due: r.due };
  }

  // Vadesi gelen döngü kelimeleri: yüksek seviye önce, eşitse en çok geciken,
  // o da eşitse katalog sırası.
  function dueList(now) {
    var s = load(), t = today(now), out = [];
    for (var k in s) if (IDX[k] != null && s[k].due <= t) out.push(k);
    out.sort(function (a, b) {
      return (s[b].b - s[a].b) || (s[a].due - s[b].due) || (IDX[a] - IDX[b]);
    });
    return out;
  }
  // Sıradaki yeni kelimeler (katalog sırasıyla). n verilmezse hepsi.
  function newList(n) {
    var s = load(), out = [];
    for (var i = 0; i < CAT.length && (n == null || out.length < n); i++)
      if (!s[CAT[i].k]) out.push(CAT[i].k);
    return out;
  }
  function examQueue(now) { return { reviews: dueList(now), news: newList() }; }

  function inCycle() { var s = load(), c = 0; for (var k in s) if (IDX[k] != null) c++; return c; }

  // Ana sayfadaki 100'lük listede bulunan en yüksek seviye etiketi.
  function topLevel(n) {
    var l = newList(n == null ? 100 : n), best = -1;
    for (var i = 0; i < l.length; i++) {
      var j = LV.indexOf(CAT[IDX[l[i]]].lv); if (j > best) best = j;
    }
    return best < 0 ? null : LV[best];
  }

  // Grup (kısım) sayaçları: olgun · öğreniliyor · yeni.
  function groupCounts(g) {
    var s = load(), c = { mature: 0, learning: 0, fresh: 0, total: 0 };
    for (var i = 0; i < CAT.length; i++) {
      if (CAT[i].g !== g) continue;
      var r = s[CAT[i].k]; c.total++;
      if (!r) c.fresh++; else if (r.b >= 4) c.mature++; else c.learning++;
    }
    return c;
  }
  function totals() {
    var s = load(), c = { mature: 0, learning: 0, fresh: 0, total: CAT.length };
    for (var i = 0; i < CAT.length; i++) {
      var r = s[CAT[i].k];
      if (!r) c.fresh++; else if (r.b >= 4) c.mature++; else c.learning++;
    }
    return c;
  }
  // En yakın gelecek vade (bugün vadesi yoksa "sonraki tekrar X gün sonra").
  function nextDue(now) {
    var s = load(), t = today(now), best = null;
    for (var k in s) if (IDX[k] != null && s[k].due > t && (best == null || s[k].due < best)) best = s[k].due;
    return best == null ? null : best - t;
  }

  function reset() { st = {}; try { localStorage.removeItem(KEY); } catch (e) {} }
  function _reload() { st = null; }   // testler için

  return {
    IV: IV, today: today, key: key,
    setCatalog: setCatalog, catalogFromGroups: catalogFromGroups,
    level: level, isNew: isNew, isDue: isDue, dirOf: dirOf, answer: answer,
    dueList: dueList, newList: newList, examQueue: examQueue,
    inCycle: inCycle, topLevel: topLevel, groupCounts: groupCounts, totals: totals,
    nextDue: nextDue, reset: reset, _reload: _reload
  };
})();

updater.js:
/*
 * Uygulama içi güncelleme.
 *
 * APK BİR KEZ kurulur (ses dosyaları içinde gömülü kalır). Arayüz (HTML/JS/CSS)
 * daha sonra küçük bir web paketiyle (web.json, ~2 MB) güncellenir;
 * yeni APK kurmaya gerek kalmaz. Ses hiç yeniden inmez.
 *
 * Çalışma:
 *  1) Daha önce indirilmiş (uygulanmış) daha yeni bir paket varsa ve hâlâ gömülü
 *     sayfadaysak, o pakete yönleniriz (dosyalar cihaz hafızasından yüklenir).
 *     Ses hep mutlak '/audio/...' yolundan APK içindeki dosyalara gider.
 *  2) Arka planda GitHub release'teki sürümü kontrol ederiz; daha yeniyse paketi
 *     indirip cihaza yazarız — bir SONRAKİ açılışta uygulanır.
 *
 * Her şey try/catch içinde: güncelleme başarısız olursa uygulama gömülü (APK'daki)
 * sürümle sorunsuz çalışmaya devam eder. Tarayıcıda (native değil) hiçbir şey yapmaz.
 */
(function () {
  var VER = 1791399437;
  var Cap = window.Capacitor;
  var native = !!(Cap && Cap.isNativePlatform && Cap.isNativePlatform());
  if (!native) return;

  function plugin(name) {
    return (Cap.Plugins && Cap.Plugins[name]) ||
           (typeof Cap.registerPlugin === "function" && Cap.registerPlugin(name));
  }
  var inUpdate = location.href.indexOf("_capacitor_file_") > -1;

  // 1) Uygulanmış güncellemeye yönlen (yalnız gömülü sayfadayken).
  try {
    var raw = localStorage.getItem("ox_webupd");
    if (raw) {
      var u = JSON.parse(raw);
      if (u && u.ver && u.base) {
        if (u.ver > VER && !inUpdate) {
          var page = location.pathname.split("/").pop() || "index.html";
          location.replace(u.base + page + location.search + location.hash);
          return;
        }
        // Yalnız GÖMÜLÜ sayfada ve gömülü sürüm işareti geçince temizle. Uygulanmış
        // pakette (inUpdate) VER==u.ver olduğundan burada temizlersek işaret silinir
        // ve kapat-aç sonrası eskiye döner — bu yüzden !inUpdate şart.
        if (u.ver <= VER && !inUpdate) { try { localStorage.removeItem("ox_webupd"); } catch (e) {} }
      }
    }
  } catch (e) {}

  // Güncellenmiş sayfadaysak ve yeni uygulandıysa küçük bilgi balonu.
  try {
    if (inUpdate && localStorage.getItem("ox_webupd_new")) {
      localStorage.removeItem("ox_webupd_new");
      window.addEventListener("DOMContentLoaded", function () {
        try {
          var t = document.createElement("div");
          t.textContent = "Uygulama güncellendi ✓";
          t.style.cssText = "position:fixed;left:50%;bottom:20px;transform:translateX(-50%);background:#2E9E5B;color:#fff;font:600 12px system-ui;padding:8px 14px;border-radius:18px;z-index:99999;box-shadow:0 4px 12px rgba(0,0,0,.3);pointer-events:none";
          document.body.appendChild(t);
          setTimeout(function () { t.style.transition = "opacity .5s"; t.style.opacity = "0"; }, 2500);
        } catch (e) {}
      });
    }
  } catch (e) {}

  // 2) Arka planda güncelleme kontrolü + indirme.
  var OWNER = "Ahmetayarsss", REPO = "thousand", BRANCH = "claude/oxford-3000-pronunciation-defs-inzs33";
  var API = "https://api.github.com/repos/" + OWNER + "/" + REPO + "/contents/";   // taze, önbeleksiz
  var RAW = "https://raw.githubusercontent.com/" + OWNER + "/" + REPO + "/refs/heads/" + BRANCH + "/";
  var REL = "https://github.com/" + OWNER + "/" + REPO + "/releases/download/apk-latest/";

  async function oneGet(url, headers) {
    try {
      var r = await fetch(url, { cache: "no-store", headers: headers || {} });
      if (r && r.ok) { var t = await r.text(); if (t) return t; }
    } catch (e) {}
    try {
      var H = plugin("CapacitorHttp");
      if (H) {
        var hd = headers || {}; hd["Cache-Control"] = "no-cache";
        var res = await H.request({ url: url, method: "GET", responseType: "text", headers: hd });
        var d = (res && res.data != null) ? ("" + res.data) : "";
        if (d) return d;
      }
    } catch (e) {}
    return "";
  }
  function toVer(s) { var t = ("" + (s || "")).trim(); return /^\d{1,20}$/.test(t) ? parseInt(t, 10) : 0; } // sadece saf sayı (404 sayfası vb. elenir)

  // Sürüm: API (taze) + raw + release → geçerli sayıların EN BÜYÜĞÜ (bayat kaynak eler).
  async function getRemoteVer() {
    var best = 0, src = "yok";
    try {
      var a = await oneGet(API + "web-version.txt?ref=" + BRANCH, { "Accept": "application/vnd.github.raw+json" });
      var n = toVer(a);
      if (!n) { try { var j = JSON.parse(a); if (j && j.content) n = toVer(atob(j.content.replace(/\s/g, ""))); } catch (e) {} }
      if (n > best) { best = n; src = "api"; }
    } catch (e) {}
    try { var n2 = toVer(await oneGet(RAW + "web-version.txt")); if (n2 > best) { best = n2; src = "raw"; } } catch (e) {}
    try { var n3 = toVer(await oneGet(REL + "web-version.txt")); if (n3 > best) { best = n3; src = "rel"; } } catch (e) {}
    return { ver: best, src: src };
  }
  async function getBundle() {
    var t = await oneGet(RAW + "web.json"); if (t && t.charAt(0) === "{") return t;
    t = await oneGet(REL + "web.json"); if (t && t.charAt(0) === "{") return t;
    return "";
  }

  // İndirip cihaza yazar ve HEMEN uygular (bir sonraki açılışı beklemeden): gömülü
  // sayfadaysak indirilen pakete yönleniriz, yeşil "güncellendi ✓" balonu çıkar.
  // Tek açılışta güncelleme olur — "iki kez kapat-aç" gerekmez.
  async function check() {
    try {
      var Fs = plugin("Filesystem");
      if (!Fs) return;
      var rv = await getRemoteVer();
      if (!rv.ver) return;
      var applied = 0;
      try { var a = JSON.parse(localStorage.getItem("ox_webupd") || "{}"); applied = a.ver || 0; } catch (e) {}
      if (rv.ver <= Math.max(VER, applied)) return; // zaten güncel

      var jtxt = await getBundle();
      if (!jtxt) return;
      var files = JSON.parse(jtxt);
      if (!files || !files["index.html"]) return;

      var dir = "webupd/v" + rv.ver;
      for (var name in files) {
        if (!Object.prototype.hasOwnProperty.call(files, name)) continue;
        await Fs.writeFile({ path: dir + "/" + name, data: String(files[name]), directory: "DATA", encoding: "utf8", recursive: true });
      }
      var uri = (await Fs.getUri({ directory: "DATA", path: dir })).uri;
      var base = Cap.convertFileSrc(uri);
      if (base.slice(-1) !== "/") base += "/";
      localStorage.setItem("ox_webupd", JSON.stringify({ ver: rv.ver, base: base }));
      localStorage.setItem("ox_webupd_new", "1");
      // Hemen uygula: gömülü sayfadaysak indirilen pakete yönlen (tek açılışta güncelle).
      if (!inUpdate) {
        var page = location.pathname.split("/").pop() || "index.html";
        location.replace(base + page + location.search + location.hash);
      }
    } catch (e) { /* sessiz: gömülü sürümle devam */ }
  }

  if (document.readyState === "complete") setTimeout(check, 600);
  else window.addEventListener("load", function () { setTimeout(check, 800); });
})();
